// tw_stock_db客製: 2026-09-11——burn_subtitles的字幕外觀預設值。尺寸/邊距
// 都用「影片高度的比例」表示，不同解析度的影片字幕看起來大小一致。使用者
// 可以在Advance Settings「子Agent」分頁改size/position。
const SUBTITLE_DEFAULT_STYLE = {
    fontScale: 0.052,
    fontFamily: '"Microsoft JhengHei", "PingFang TC", "Noto Sans CJK TC", "Hiragino Sans", "Heiti TC", sans-serif',
    color: '#ffffff',
    strokeColor: '#000000',
    strokeScale: 0.16,
    position: 'bottom',
    marginScale: 0.055,
    maxWidthFrac: 0.9,
    lineHeightScale: 1.28,
    background: 'rgba(0,0,0,0.4)',
    paddingScale: 0.28,
};
// tw_stock_db客製: 2026-09-11——transcribe_media產生逐字稿檔案時，把秒數
// 格式化成 M:SS 或 H:MM:SS（超過一小時才顯示小時位）。null/NaN回傳"?:??"，
// 讓「模型沒吐出這一段的時間軸」的情況在檔案裡看得出來、不會靜靜變成0。
function _faFormatTimestamp(seconds) {
    if (seconds == null || !Number.isFinite(seconds)) return '?:??';
    const total = Math.max(0, Math.floor(seconds));
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    return h > 0
        ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
        : `${m}:${String(s).padStart(2, '0')}`;
}

// tw_stock_db客製: 2026-09-11——SubRip(.srt)字幕的時間格式 HH:MM:SS,mmm。
// null/NaN當0處理（.srt格式沒有「未知時間」這種東西，寧可給0也不要產生
// 不合法的.srt）。
function _faFormatSrtTime(seconds) {
    const total = Math.max(0, Number.isFinite(seconds) ? seconds : 0);
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = Math.floor(total % 60);
    const ms = Math.round((total - Math.floor(total)) * 1000);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
}

// tw_stock_db客製: 2026-09-11——segments[{start,end,text}]轉成.srt字幕檔內容。
function _faSegmentsToSrt(segments) {
    return segments.map((s, i) => {
        const end = (s.end != null && s.end > s.start) ? s.end : (s.start || 0) + 2;
        return `${i + 1}\n${_faFormatSrtTime(s.start)} --> ${_faFormatSrtTime(end)}\n${s.text}\n`;
    }).join('\n');
}

// tw_stock_db客製: 2026-09-12——依副檔名把上傳的檔案粗分類，讓 /media-*
// slash 指令在「一次附加多個檔案（例如 mp4 + srt）」時能自己挑對：影音檔
// 當來源、字幕檔當字幕，不會拿 .srt 去當影片解碼。
function _faClassifyMediaFile(filename) {
    const ext = String(filename || '').toLowerCase().match(/\.([a-z0-9]+)$/);
    const e = ext ? ext[1] : '';
    if (['mp4', 'mov', 'mkv', 'webm', 'avi', 'm4v', 'mpg', 'mpeg', '3gp', 'ogv'].includes(e)) return 'video';
    if (['mp3', 'wav', 'm4a', 'aac', 'ogg', 'oga', 'flac', 'opus', 'weba', 'wma'].includes(e)) return 'audio';
    if (['srt', 'vtt', 'ass', 'ssa', 'sbv'].includes(e)) return 'subtitle';
    if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg', 'avif', 'ico'].includes(e)) return 'image';
    // tw_stock_db客製: 2026-09-24使用者要求——附件貼上PDF要有viewer可以看，
    // 跟image縮圖同一種「分類出來才知道要不要顯示可互動UI」的用法。
    if (e === 'pdf') return 'pdf';
    return 'other';
}

// tw_stock_db客製: 2026-09-11——把.srt字幕檔、或transcribe_media早期版本的
// 「[M:SS - M:SS] 文字」逐行格式，解析回segments[{start,end,text}]。
// 給燒錄字幕吃「使用者自己提供的字幕檔」用。
function _faParseSubtitleText(text) {
    const raw = String(text || '').replace(/\r\n/g, '\n').trim();
    if (!raw) return [];
    const toSec = (hms) => {
        // 支援 HH:MM:SS,mmm / HH:MM:SS.mmm / MM:SS / M:SS
        const m = hms.trim().match(/^(?:(\d+):)?(\d{1,2}):(\d{1,2})(?:[.,](\d{1,3}))?$/);
        if (!m) return null;
        const h = m[1] ? +m[1] : 0;
        return h * 3600 + (+m[2]) * 60 + (+m[3]) + (m[4] ? +('0.' + m[4]) : 0);
    };
    const segs = [];
    // .srt: 區塊之間用空行分隔，每塊 序號\n 開始 --> 結束\n 文字...
    if (/-->/.test(raw)) {
        for (const block of raw.split(/\n{2,}/)) {
            const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
            const tl = lines.find(l => l.includes('-->'));
            if (!tl) continue;
            const [a, b] = tl.split('-->').map(x => x.trim());
            const start = toSec(a), end = toSec(b);
            const textLines = lines.slice(lines.indexOf(tl) + 1);
            if (start == null || !textLines.length) continue;
            segs.push({ start, end: end != null ? end : start + 2, text: textLines.join(' ').trim() });
        }
        return segs;
    }
    // 「[M:SS - M:SS] 文字」逐行
    for (const line of raw.split('\n')) {
        const m = line.match(/^\s*\[\s*([\d:.,?]+)\s*[-–]\s*([\d:.,?]+)\s*\]\s*(.+)$/);
        if (!m) continue;
        const start = toSec(m[1]), end = toSec(m[2]);
        if (start == null) continue;
        segs.push({ start, end: end != null ? end : start + 2, text: m[3].trim() });
    }
    return segs;
}

// tw_stock_db客製: 2026-09-11——把一個AudioBuffer編成16-bit PCM WAV Blob
// （擷取聲音功能用）。純JS、不需要任何函式庫。多聲道交錯寫入。
function _faEncodeWav(audioBuffer) {
    const numCh = audioBuffer.numberOfChannels;
    const sr = audioBuffer.sampleRate;
    const nSamples = audioBuffer.length;
    const chans = [];
    for (let c = 0; c < numCh; c++) chans.push(audioBuffer.getChannelData(c));
    const dataBytes = nSamples * numCh * 2;
    const buf = new ArrayBuffer(44 + dataBytes);
    const dv = new DataView(buf);
    const ws = (o, s) => { for (let i = 0; i < s.length; i++) dv.setUint8(o + i, s.charCodeAt(i)); };
    ws(0, 'RIFF'); dv.setUint32(4, 36 + dataBytes, true); ws(8, 'WAVE'); ws(12, 'fmt ');
    dv.setUint32(16, 16, true); dv.setUint16(20, 1, true); dv.setUint16(22, numCh, true);
    dv.setUint32(24, sr, true); dv.setUint32(28, sr * numCh * 2, true);
    dv.setUint16(32, numCh * 2, true); dv.setUint16(34, 16, true);
    ws(36, 'data'); dv.setUint32(40, dataBytes, true);
    let off = 44;
    for (let i = 0; i < nSamples; i++) {
        for (let c = 0; c < numCh; c++) {
            let v = Math.max(-1, Math.min(1, chans[c][i]));
            dv.setInt16(off, v < 0 ? v * 0x8000 : v * 0x7fff, true);
            off += 2;
        }
    }
    return new Blob([buf], { type: 'audio/wav' });
}

// tw_stock_db客製: 2026-09-12——用已載入好的全域lamejs把PCM樣本編成MP3
// Blob（純函式，呼叫端要先確保lamejs已經載入——見_ensureLamejsLoaded）。
// extract_audio（省persistentStorage空間，使用者要求）跟text_to_speech
// 兩處共用同一個編碼路徑，各自把來源（AudioBuffer / Kokoro產生的Float32
// 樣本）轉成Int16聲道陣列後餵進來。lame的encodeBuffer/encodeBuffer(l,r)
// 一次吃一個chunk（用官方範例的1152這個frame size），flush()拿最後剩餘的。
// tw_stock_db客製: 2026-09-14使用者回報/media-text-to-speech會卡住UI一段
// 時間——這個迴圈原本完全同步、中間沒有任何yield，幾秒鐘的音訊要編碼成
// 幾萬~幾十萬個PCM樣本，全部擠在同一個JS執行tick跑完，瀏覽器在這段時間
// 完全沒機會重繪畫面/回應使用者操作（點擊、捲動都會卡住）。改成async、
// 每處理滿YIELD_EVERY_CHUNKS個1152-sample chunk就await一次
// setTimeout(resolve,0)，把控制權還給事件迴圈一下——實測不影響最終編碼
// 結果（純粹把同一份運算切成很多小段分開跑，總運算量不變），只是讓長音訊
// 編碼時瀏覽器仍然能回應。呼叫端本來就都在async函式裡（見下面兩個呼叫
// 點），改成await即可，不需要額外處理。
// ⚠️已知限制：這只解決了MP3編碼這一段的卡頓，本地Kokoro TTS本身的模型
// 推論（engine.generate()，純WASM、CPU同步執行）仍然會佔用主執行緒一段
// 時間，沒有一併解決——真正徹底解決需要把Kokoro搬進Web Worker執行，是
// 更大幅度的架構調整，這次沒有做。
async function _faLamejsEncode(channelsInt16, sampleRate, bitrateKbps) {
    const numCh = channelsInt16.length;
    const encoder = new lamejs.Mp3Encoder(numCh, sampleRate, bitrateKbps || 128);
    const chunkSize = 1152;
    const mp3Chunks = [];
    const total = channelsInt16[0].length;
    // tw_stock_db客製: 2026-09-14實測修正——原本設200太高，1152-sample
    // chunk在24000Hz下大約每秒20個chunk，一般TTS輸出只有幾秒鐘長，200這個
    // 門檻幾乎不會被觸發到（等於没有真的在yield）。實測用OfflineAudioContext
    // 產生10秒音訊編碼，200門檻下事件迴圈整段完全沒機會跑（0次interval
    // tick）；每個chunk編碼約2ms，改成每16個chunk（約32ms）yield一次，能讓
    // 長音訊編碼時瀏覽器仍然定期有機會重繪/回應，短音訊（多數TTS情境）也
    // 至少能yield個幾次。
    const YIELD_EVERY_CHUNKS = 16;
    let chunkCount = 0;
    for (let i = 0; i < total; i += chunkSize) {
        const left = channelsInt16[0].subarray(i, i + chunkSize);
        const right = numCh > 1 ? channelsInt16[1].subarray(i, i + chunkSize) : undefined;
        const buf = numCh > 1 ? encoder.encodeBuffer(left, right) : encoder.encodeBuffer(left);
        if (buf.length > 0) mp3Chunks.push(buf);
        chunkCount++;
        if (chunkCount % YIELD_EVERY_CHUNKS === 0) {
            await new Promise(resolve => setTimeout(resolve, 0));
        }
    }
    const end = encoder.flush();
    if (end.length > 0) mp3Chunks.push(end);
    return new Blob(mp3Chunks, { type: 'audio/mpeg' });
}

// tw_stock_db客製: 2026-09-12——Float32（-1~1）樣本轉Int16 PCM，MP3/WAV
// 編碼共用的量化邏輯（跟_faEncodeWav裡那段inline的算法一致，這裡抽出來給
// _faLamejsEncode的呼叫端重用，避免兩處各自寫一次同樣的截幅公式）。
function _faFloat32ToInt16(f32) {
    const out = new Int16Array(f32.length);
    for (let i = 0; i < f32.length; i++) {
        const v = Math.max(-1, Math.min(1, f32[i]));
        out[i] = v < 0 ? v * 0x8000 : v * 0x7fff;
    }
    return out;
}

function _faSetAssetUrls(overrides) {
    Object.assign(FA_ASSET_URLS, overrides || {});
}

// tw_stock_db客製: 2026-09-11——字幕繪製（主執行緒版）。跟
// FA_BURN_SUBTITLES_WORKER_SRC裡的_wrapLines/_drawSubtitle是**同一份邏輯的
// 複製**（worker src是字串沒辦法共用函式參照），兩份要保持一致。這個版本
// 給compose_video在主執行緒逐幀疊字幕用（burn_subtitles是在worker裡疊）。
function _faWrapSubtitleLines(ctx, text, maxWidth) {
    const out = [];
    for (const para of String(text || '').split('\n')) {
        let line = '';
        for (const tok of para.split(/(\s+)/)) {
            if (!tok) continue;
            if (ctx.measureText(line + tok).width <= maxWidth) { line += tok; continue; }
            if (line.trim()) out.push(line.trim());
            line = '';
            if (ctx.measureText(tok).width > maxWidth) {
                let chunk = '';
                for (const ch of Array.from(tok)) {
                    if (ctx.measureText(chunk + ch).width <= maxWidth) chunk += ch;
                    else { if (chunk) out.push(chunk); chunk = ch; }
                }
                line = chunk;
            } else { line = tok.replace(/^\s+/, ''); }
        }
        if (line.trim()) out.push(line.trim());
    }
    return out.length ? out : [''];
}
function _faDrawSubtitle(ctx, tSec, segments, style) {
    let seg = null;
    for (const s of segments) {
        const end = (s.end != null && s.end > s.start) ? s.end : s.start + 3;
        if (tSec >= s.start - 0.05 && tSec < end + 0.05) { seg = s; break; }
    }
    if (!seg || !seg.text) return;
    const W = ctx.canvas.width, H = ctx.canvas.height;
    const fs = Math.max(10, Math.round(H * style.fontScale));
    ctx.save();
    ctx.font = 'bold ' + fs + 'px ' + style.fontFamily;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    const maxW = W * style.maxWidthFrac;
    const lines = _faWrapSubtitleLines(ctx, seg.text, maxW);
    const lh = fs * style.lineHeightScale;
    const blockH = lh * (lines.length - 1) + fs;
    const pad = fs * style.paddingScale;
    let firstBaseline;
    if (style.position === 'top') firstBaseline = H * style.marginScale + fs;
    else firstBaseline = H - H * style.marginScale - blockH + fs;
    if (style.background) {
        let boxW = 0;
        for (const ln of lines) boxW = Math.max(boxW, ctx.measureText(ln).width);
        boxW = Math.min(W, boxW + pad * 2);
        const boxX = (W - boxW) / 2;
        const boxY = firstBaseline - fs - pad * 0.7;
        const boxH = blockH + pad * 1.4;
        ctx.fillStyle = style.background;
        if (ctx.roundRect) { ctx.beginPath(); ctx.roundRect(boxX, boxY, boxW, boxH, Math.min(pad, 12)); ctx.fill(); }
        else ctx.fillRect(boxX, boxY, boxW, boxH);
    }
    ctx.lineWidth = Math.max(1, fs * style.strokeScale);
    ctx.lineJoin = 'round';
    ctx.strokeStyle = style.strokeColor;
    ctx.fillStyle = style.color;
    for (let i = 0; i < lines.length; i++) {
        const y = firstBaseline + i * lh;
        if (ctx.lineWidth > 0.5) ctx.strokeText(lines[i], W / 2, y);
        ctx.fillText(lines[i], W / 2, y);
    }
    ctx.restore();
}
// tw_stock_db客製: 2026-09-05使用者要求（計畫文件階段3的「已完成的部分」
// 項目3）——PPTX匯出的視覺識別要換成適合這個台股專案的風格，不要沿用
// redmine參考版本的Default品牌配色。這裡選深藏青（信任/專業，金融業常見
// 基調色）+金色（股票代碼機常見的暖色點綴，呼應「台股」語境），不是隨便
// 換一個顏色——navy/accent兩色刻意保持強烈明暗對比，其餘皆為輔助中性色。
const FA_EXPORT_PALETTE = { navy: '0B1E3D', accent: 'C9A227', accentDark: '8A6E17', txt: '333333', muted: '888888', border: 'DDDDDD', tileGray: 'F5F6FA', white: 'FFFFFF' };

// tw_stock_db客製: 標題投影片背景——不用靜態圖片檔案（這個專案沒有伺服器
// 附件系統可以vendor圖片資源，見計畫文件對texture_attachment_id的說明，
// 同樣的限制在這裡也適用），改成在匯出當下用canvas程序生成一張淡淡的
// 股價走勢面積圖當背景紋理（深藏青漸層底色+低透明度的金色走勢線+填色），
// 呼應「台股」主題但不會蓋過上面疊的標題文字。只在真的要匯出標題投影片
// 時才呼叫，不是每次載入都要背這個運算成本。
function _faGeneratePptxTitleBackgroundDataUri() {
    const w = 1280, h = 720;
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext('2d');
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, '#0B1E3D');
    grad.addColorStop(1, '#16305C');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    const n = 24;
    const points = [];
    let y = h * 0.62;
    for (let i = 0; i <= n; i++) {
        y += (Math.sin(i * 0.7) + (Math.random() - 0.5)) * 14;
        y = Math.max(h * 0.45, Math.min(h * 0.8, y));
        points.push({ x: (i / n) * w, y });
    }
    // tw_stock_db客製: 第一版純色低透明度填色在深藏青底色上會被吃成灰藍色，
    // 完全看不出「金色」——改用由淡轉濃的垂直漸層填色（越靠底部越實色），
    // 讓面積圖底部有足夠彩度撐住金色，頂部邊緣仍維持淡出、不搶標題文字。
    const fillGrad = ctx.createLinearGradient(0, h * 0.4, 0, h);
    fillGrad.addColorStop(0, 'rgba(201,162,39,0.05)');
    fillGrad.addColorStop(1, 'rgba(201,162,39,0.4)');
    ctx.beginPath();
    ctx.moveTo(0, h);
    points.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.lineTo(w, h);
    ctx.closePath();
    ctx.fillStyle = fillGrad;
    ctx.fill();

    ctx.strokeStyle = '#F0C94D';
    ctx.lineWidth = 3;
    ctx.beginPath();
    points.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
    ctx.stroke();
    return canvas.toDataURL('image/png');
}

// tw_stock_db客製: 2026-08-28使用者要求把匯出用的外部函式庫vendor到自己的
// GitHub repo（見FA_ASSET_URLS），vendor完之後瀏覽器實測發現一個重要限制：
// raw.githubusercontent.com（vendor資源放置處）每個檔案的回應一律帶
// `Content-Type: text/plain` + `X-Content-Type-Options: nosniff`，這是
// GitHub刻意的安全設計（避免raw.githubusercontent.com被當成公開JS/CSS CDN
// 濫用），瀏覽器看到nosniff+非JS/CSS的MIME類型時，會直接拒絕把回應內容
// 當<script>/<link rel=stylesheet>執行/套用——長期不會改變，不是暫時性
// 問題。實測驗證：對同一個網址直接用<script src=...>四連發全部失敗，改用
// fetch()卻100%成功（fetch()本身不受回應MIME類型限制，單純把回應當
// bytes/text處理）。字型(@font-face url())不受這個限制影響，不需要處理。
//
// 解法：fetch()抓下內容→包成Blob（自己指定正確的MIME type，不理會伺服器
// 回應的Content-Type）→用Blob URL當<script src>/<link href>，繞過nosniff
// 限制。sql.js本身的wasm是initSqlJs內部自己走fetch機制載入（不是
// <script>/<link>），不受影響，不需要處理（見index.html的initSqlJs呼叫）。
const _faExportScriptCache = new Map();
function _faLoadScriptOnce(url) {
    if (_faExportScriptCache.has(url)) return _faExportScriptCache.get(url);
    const p = fetch(url)
        .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.text(); })
        .then(text => new Promise((resolve, reject) => {
            // 回應是一句很短、完全沒有程式碼特徵的文字（例如Cloudflare Worker沒有這條路由時的catch-all
            // 「Worker運作正常。」）——不是JavaScript，直接當載入失敗，不要包成script執行。
            if (text.length < 300 && !/[;{}=]/.test(text)) { reject(new Error('回應內容不是JavaScript：' + text.slice(0, 40))); return; }
            const blob = new Blob([text], { type: 'application/javascript' });
            const blobUrl = URL.createObjectURL(blob);
            const s = document.createElement('script');
            s.src = blobUrl;
            s.onload = () => { URL.revokeObjectURL(blobUrl); resolve(); };
            s.onerror = () => { URL.revokeObjectURL(blobUrl); reject(new Error(`匯出功能所需的外部程式庫執行失敗：${url}`)); };
            document.head.appendChild(s);
        }))
        .catch(e => { _faExportScriptCache.delete(url); throw new Error(`匯出功能所需的外部程式庫載入失敗：${url}（${e.message}）`); });
    _faExportScriptCache.set(url, p);
    return p;
}

// tw_stock_db客製: 2026-09-05——給FA_3D_IMPORT_WORKER_SRC用，只需要拿到
// 純文字內容（在worker自己的global scope裡indirect eval執行），不需要
// 像_faLoadScriptOnce那樣包Blob URL再用<script>標籤注入——fetch()本身
// 不受nosniff限制（見上面_faLoadScriptOnce的說明），直接拿文字就夠用。
// 獨立一份cache（不跟_faExportScriptCache共用），避免兩種不同用途
// 互相干擾。
const _faScriptTextCache = new Map();
function _faFetchScriptText(url) {
    if (_faScriptTextCache.has(url)) return _faScriptTextCache.get(url);
    const p = fetch(url)
        .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.text(); })
        .catch(e => { _faScriptTextCache.delete(url); throw e; });
    _faScriptTextCache.set(url, p);
    return p;
}

// katex.min.css用相對路徑url(fonts/xxx)引用字型檔，Blob URL沒有「目錄」
// 概念、相對路徑解析會全部失效，這裡在包成Blob之前，先把CSS內容裡的
// 相對路徑改寫成絕對網址（rewriteBaseUrl，指向katex vendor資料夾），字型
// 本身不受nosniff限制（見上方說明），可以直接指向raw.githubusercontent.com。
// elementId選填：因為套用的是Blob URL，href不會再帶原始網址的字樣，呼叫端
// 沒辦法再用「href包含某關鍵字」去判斷「這個樣式表是不是已經套用過」，改成
// 由這裡直接把id設在建立出來的<link>上，呼叫端改用document.getElementById
// 判斷即可（見_ensureMarkdownLibsLoaded的katex.min.css用法）。
function _faLoadStyleOnce(url, rewriteBaseUrl, elementId) {
    const cacheKey = 'style:' + url;
    if (_faExportScriptCache.has(cacheKey)) return _faExportScriptCache.get(cacheKey);
    const p = fetch(url)
        .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.text(); })
        .then(text => {
            if (rewriteBaseUrl) {
                text = text.replace(/url\((?!['"]?(?:https?:|data:|blob:))(['"]?)([^'")]+)\1\)/g, (m, q, path) => `url(${q}${rewriteBaseUrl}${path}${q})`);
            }
            return new Promise((resolve, reject) => {
                const blob = new Blob([text], { type: 'text/css' });
                const blobUrl = URL.createObjectURL(blob);
                const l = document.createElement('link');
                if (elementId) l.id = elementId;
                l.rel = 'stylesheet';
                l.href = blobUrl;
                l.onload = () => { URL.revokeObjectURL(blobUrl); resolve(); };
                l.onerror = () => { URL.revokeObjectURL(blobUrl); reject(new Error(`樣式表套用失敗：${url}`)); };
                document.head.appendChild(l);
            });
        })
        .catch(e => { _faExportScriptCache.delete(cacheKey); throw new Error(`樣式表載入失敗：${url}（${e.message}）`); });
    _faExportScriptCache.set(cacheKey, p);
    return p;
}

function _faArrayBufferToBase64(buf) {
    let binary = '';
    const bytes = new Uint8Array(buf);
    const chunkSize = 0x8000; // 32KB一塊，避免String.fromCharCode.apply一次吃進太多引數爆呼叫堆疊
    for (let i = 0; i < bytes.length; i += chunkSize) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
    }
    return btoa(binary);
}

let _faCjkFontPromise = null;
async function _faEnsureCjkFontRegistered() {
    if (_faCjkFontPromise) return _faCjkFontPromise;
    _faCjkFontPromise = (async () => {
        const pdfMake = window.pdfMake;
        const [regularBuf, boldBuf] = await Promise.all([
            fetch(FA_ASSET_URLS.cjkFontRegular).then(r => { if (!r.ok) throw new Error('中文字型下載失敗'); return r.arrayBuffer(); }),
            fetch(FA_ASSET_URLS.cjkFontBold).then(r => { if (!r.ok) throw new Error('中文字型(粗體)下載失敗'); return r.arrayBuffer(); }),
        ]);
        pdfMake.vfs = pdfMake.vfs || {};
        pdfMake.vfs['NotoSansTC-Regular.ttf'] = _faArrayBufferToBase64(regularBuf);
        pdfMake.vfs['NotoSansTC-Bold.ttf'] = _faArrayBufferToBase64(boldBuf);
        pdfMake.fonts = Object.assign({}, pdfMake.fonts, {
            NotoSansTC: {
                normal: 'NotoSansTC-Regular.ttf', bold: 'NotoSansTC-Bold.ttf',
                italics: 'NotoSansTC-Regular.ttf', bolditalics: 'NotoSansTC-Bold.ttf',
            },
        });
    })();
    return _faCjkFontPromise;
}

// 上面載入的Noto Sans TC「chinese-traditional」子集字型經opentype.js實測
// charToGlyphIndex()確認缺這10個全形標點的字圖（.notdef），pdfmake找不到
// 字圖時畫出豆腐字方塊，轉成對應半形符號保證能顯示；其餘全形標點
// （。、「」『』【】—）這個子集有涵蓋，不轉換。
const FA_PDF_MISSING_PUNCT = { '！': '!', '％': '%', '（': '(', '）': ')', '－': '-', '：': ':', '；': ';', '？': '?', '～': '~', '，': ',' };
function _faSanitizePdfText(s) {
    if (s == null) return s;
    return String(s).replace(/[！％（）－：；？～，]/g, ch => FA_PDF_MISSING_PUNCT[ch] || ch);
}

function _faSplitMarkdownSections(text) {
    const lines = String(text || '').split('\n');
    const sections = [];
    let cur = { title: null, body: [] };
    for (const line of lines) {
        const m = /^#{1,3}\s+(.+?)\s*$/.exec(line);
        if (m) {
            if (cur.title !== null || cur.body.some(l => l.trim() !== '')) sections.push(cur);
            cur = { title: m[1], body: [] };
        } else {
            cur.body.push(line);
        }
    }
    if (cur.title !== null || cur.body.some(l => l.trim() !== '')) sections.push(cur);
    return sections.map(s => ({ title: s.title, body: s.body.join('\n').trim() }));
}

// tw_stock_db客製: 2026-09-22使用者回報投影片文字會重疊/溢出——原本只在
// 「段落之間」（空行分隔）判斷要不要切到下一張投影片，單一段落本身超過
// maxChars（AI整段沒換行）完全不會被切，整段塞進一張投影片固定大小的
// 文字框，超出框高的部分在PowerPoint裡視覺上會蓋出框外/超出投影片邊界。
// 這裡補上「單一段落也要在maxChars內切」：先照單行(\n)切，單行仍然太長
// 再照字元數硬切，確保任何一個chunk都不會遠超過maxChars。
function _faChunkTextByLength(body, maxChars) {
    const paras = String(body || '').split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
    const splitOversizedPara = (p) => {
        if (p.length <= maxChars) return [p];
        const lines = p.split('\n');
        const out = [];
        let buf = '';
        for (const line of lines) {
            const candidate = buf ? buf + '\n' + line : line;
            if (candidate.length > maxChars && buf) { out.push(buf); buf = line; } else buf = candidate;
            while (buf.length > maxChars) { out.push(buf.slice(0, maxChars)); buf = buf.slice(maxChars); }
        }
        if (buf) out.push(buf);
        return out;
    };
    const chunks = [];
    let cur = '', curLen = 0;
    for (const rawP of paras) {
        for (const p of splitOversizedPara(rawP)) {
            if (curLen && curLen + p.length + 2 > maxChars) { chunks.push(cur); cur = ''; curLen = 0; }
            cur += (cur ? '\n\n' : '') + p; curLen += p.length;
        }
    }
    if (cur || !chunks.length) chunks.push(cur);
    return chunks;
}

// 偵測markdown pipe table（表頭列 + |---|---|分隔列），AI寫的表格內容
// 原本會被當純文字整段印出來（"| a | b |"原始語法），這裡解析成
// {columns, rows}丟給下面的faMarkdownToPptxBlob/faMarkdownToPdfBlob畫成
// 真正的表格。cell內容偶爾會塞"<br>"當作cell內分行（markdown表格語法
// 本身不能有真正的換行），順便轉成"\n"實際換行。
function _faIsTableSeparatorLine(line) {
    return /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/.test(line);
}
function _faIsTableRowLine(line) {
    return line.includes('|') && line.trim() !== '';
}
function _faParseTableCell(v) {
    return String(v ?? '').trim().replace(/<br\s*\/?>/gi, '\n');
}
function _faParseTableRow(line) {
    let t = line.trim();
    if (t.startsWith('|')) t = t.slice(1);
    if (t.endsWith('|')) t = t.slice(0, -1);
    return t.split('|').map(_faParseTableCell);
}
function _faSplitMarkdownBlocks(text) {
    const lines = String(text || '').split('\n');
    const blocks = [];
    let textBuf = [];
    const flushText = () => {
        const body = textBuf.join('\n').trim();
        if (body) blocks.push({ type: 'text', body });
        textBuf = [];
    };
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (_faIsTableRowLine(line) && i + 1 < lines.length && _faIsTableSeparatorLine(lines[i + 1])) {
            flushText();
            const columns = _faParseTableRow(line);
            let j = i + 2;
            const rows = [];
            while (j < lines.length && _faIsTableRowLine(lines[j])) { rows.push(_faParseTableRow(lines[j])); j++; }
            blocks.push({ type: 'table', columns, rows });
            i = j - 1;
        } else {
            textBuf.push(line);
        }
    }
    flushText();
    return blocks;
}

// 給PPTX/PDF這種不吃markdown語法的純文字版面用：拿掉**/-符號，條列改用
// 純文字項目符號。
function _faMdLiteToPlainText(text) {
    return String(text || '')
        .split('\n')
        .map(line => {
            const bullet = /^\s*[-*]\s+(.+)$/.exec(line);
            if (bullet) return '• ' + bullet[1].replace(/\*\*(.+?)\*\*/g, '$1').replace(/(?<!\*)\*(?!\*)(.+?)\*(?!\*)/g, '$1');
            return line.replace(/\*\*(.+?)\*\*/g, '$1').replace(/(?<!\*)\*(?!\*)(.+?)\*(?!\*)/g, '$1');
        })
        .join('\n');
}

// 把一段AI寫的markdown拆成{type:'text'|'table', heading, body|columns/rows}
// 陣列——依#/##/###標題分段、每段再依表格邊界拆block、單一text block過長
// （>900字）再依段落邊界分頁，PPTX跟PDF共用同一份轉換結果。
function _faMarkdownToSlides(markdownText, heading) {
    const sections = _faSplitMarkdownSections(markdownText);
    const secList = sections.length ? sections : [{ title: null, body: markdownText }];
    const slides = [];
    secList.forEach(sec => {
        const secTitle = sec.title || heading;
        _faSplitMarkdownBlocks(sec.body).forEach(block => {
            if (block.type === 'table') {
                slides.push({ type: 'table', heading: secTitle, columns: block.columns, rows: block.rows });
            } else {
                const chunks = _faChunkTextByLength(block.body, 900);
                const n = chunks.length;
                chunks.forEach((body, i) => {
                    slides.push({ type: 'text', heading: n > 1 ? `${secTitle}（${i + 1}/${n}）` : secTitle, body });
                });
            }
        });
    });
    return slides;
}

// tw_stock_db客製: 2026-09-05使用者明確要求——對話中出現3D場景/互動viewer/
// 通用繪圖時，使用者把回覆匯出成PPTX（或PDF）也要能把這些視覺內容一併
// 放進去，不能只匯出文字。做法比照redmine參考文件PROMPT.md §13（見那邊
// 的rasterizeIfSvg說明）的精神——不管畫面/PDF/PPTX，最終都是「把視覺內容
// 轉成一張PNG圖片再嵌進去」，差別只在於這個無後端架構沒有伺服器附件URL可
// 抓，改成直接對這個對話輪次裡實際渲染過的DOM節點（3D canvas / SVG）
// 截圖，見FloatingAssistant.prototype._collectTurnVisualSnapshots/
// _captureVisualSnapshot。visualSnapshots是選填的{dataUrl,kind}陣列，
// 沒有提供時行為完全不變（純文字/表格投影片）。
async function _faAppendVisualSnapshotSlides(pres, addHeadingSlideBase, visualSnapshots) {
    const KIND_LABEL = { image: '🖼️ 圖表', scene3d: '🧊 3D場景', drawing: '🎨 繪圖', mermaid: '📊 UML/流程圖', viewer_summary: '📝 互動表單內容', terminal: '🖥️ 終端機記錄' };
    for (const snap of (visualSnapshots || [])) {
        if (!snap) continue;
        const s = addHeadingSlideBase(KIND_LABEL[snap.kind] || '視覺內容');
        try {
            // tw_stock_db客製: 互動viewer是文字摘要（kind==='viewer_summary'，
            // 見_summarizeViewerStateForExport），不是截圖——表單填寫內容用
            // 文字呈現比像素截圖更有報告價值。其餘kind都是dataUrl截圖。
            // tw_stock_db客製: 2026-09-18——終端機（kind==='terminal'，見
            // _captureTerminalScreenText）同樣是純文字，跟viewer_summary
            // 共用這個文字render分支。
            if ((snap.kind === 'viewer_summary' || snap.kind === 'terminal') && snap.text) {
                s.addText(_faMdLiteToPlainText(snap.text), { x: 0.6, y: 1.3, w: 12.1, h: 5.7, fontFace: 'Calibri', fontSize: 14, color: FA_EXPORT_PALETTE.txt, align: 'left', valign: 'top', lineSpacingMultiple: 1.3, fit: 'shrink' });
            } else if (snap.dataUrl) {
                // tw_stock_db客製: 2026-09-22使用者要求——原本不管圖片本身是
                // 直的還是橫的，一律塞進同一個固定的橫向10.3x5.7方框（靠
                // sizing:{type:'contain'}宣稱會等比例縮放）。**實測發現
                // sizing:{type:'contain'}並不會真的等比例縮放**——用真實
                // Electron+python-pptx/LibreOffice渲染驗證，400x900的直式
                // 測試圖丟進6.2x5.7的方框後，畫面呈現的是被拉伸成接近方框
                // 比例的長方形，不是保留原始比例、置中留白的效果（pptxgenjs
                // 這個選項的實際行為跟文件描述的字面意思對不上，不能信任）。
                // 改成完全不依賴sizing選項：自己讀圖片實際寬高
                // （_faGetImageNaturalSize，跟PDF那邊同一個函式）、自己算出
                // 「不超過可用範圍」的等比例縮放後寬高，直接把這個算好的
                // 寬高當成addImage本身的w/h（不是外框的w/h）——跟PDF路徑
                // 「自己算出width+height兩個值都給，不依賴函式庫自動處理」
                // 是同一個做法，這樣不管pptxgenjs的sizing選項實際行為是什麼
                // 都不影響結果。長寬比仍然用來決定「最大可用寬度」（明顯
                // 直式的圖給較窄的可用寬度、明顯橫式的給較寬的），避免直式
                // 圖片因為可用寬度設太大而在計算等比例縮放時被寬度而不是
                // 高度卡住、反而縮得比預期小。
                const SLIDE_W = 13.3, SLIDE_H = 7.5, TOP = 1.3, BOTTOM_MARGIN = 0.5;
                const maxAvailH = SLIDE_H - TOP - BOTTOM_MARGIN;
                let natural = null;
                try { natural = await _faGetImageNaturalSize(snap.dataUrl); } catch (_) { /* 讀不到自然尺寸時退回下面的保底方框 */ }
                let boxW = 10.3, boxH = maxAvailH;
                if (natural && natural.w > 0 && natural.h > 0) {
                    const ratio = natural.w / natural.h;
                    const maxW = ratio <= 0.8 ? 6.2 : (ratio >= 1.3 ? 10.3 : 7.6);
                    const scale = Math.min(maxW / natural.w, maxAvailH / natural.h, 1); // 不放大原本就小的圖
                    boxW = natural.w * scale;
                    boxH = natural.h * scale;
                }
                const boxX = (SLIDE_W - boxW) / 2;
                const boxY = TOP + Math.max(0, (maxAvailH - boxH) / 2);
                s.addImage({ data: snap.dataUrl, x: boxX, y: boxY, w: boxW, h: boxH });
            }
        } catch (_) { /* 個別截圖/摘要嵌入失敗不影響其餘投影片 */ }
    }
}

async function _faMarkdownToPptxBlob(markdownText, heading, visualSnapshots) {
    await _faLoadScriptOnce(FA_ASSET_URLS.pptxgenjs);
    const PptxGenJS = window.PptxGenJS;
    const pres = new PptxGenJS();
    pres.layout = 'LAYOUT_WIDE'; // 13.3"x7.5"，預設是10"寬的16x9，要先設過再addSlide
    pres.title = heading;

    const titleSlide = pres.addSlide();
    try {
        titleSlide.background = { data: _faGeneratePptxTitleBackgroundDataUri() };
    } catch (_) {
        titleSlide.background = { color: FA_EXPORT_PALETTE.navy }; // canvas生成失敗時的保底純色背景
    }
    titleSlide.addText(heading, { x: 0.8, y: 2.5, w: 11.7, h: 1.2, fontFace: 'Calibri', fontSize: 32, bold: true, color: FA_EXPORT_PALETTE.white, align: 'center' });
    titleSlide.addText(new Date().toLocaleDateString('zh-TW'), { x: 0.8, y: 3.7, w: 11.7, h: 0.5, fontFace: 'Calibri', fontSize: 14, color: FA_EXPORT_PALETTE.accent, align: 'center' });

    const addHeadingSlideBase = (slideHeading) => {
        const s = pres.addSlide();
        s.background = { color: FA_EXPORT_PALETTE.white };
        s.addText(slideHeading || '', { x: 0.6, y: 0.4, w: 12.1, h: 0.6, fontFace: 'Calibri', fontSize: 22, bold: true, color: FA_EXPORT_PALETTE.navy });
        return s;
    };

    _faMarkdownToSlides(markdownText, heading).forEach((slide) => {
        const s = addHeadingSlideBase(slide.heading);
        if (slide.type === 'table') {
            const headerRow = (slide.columns || []).map(c => ({ text: String(c ?? ''), options: { bold: true, color: FA_EXPORT_PALETTE.white, fill: { color: FA_EXPORT_PALETTE.navy }, fontSize: 12 } }));
            const bodyRows = (slide.rows || []).map((r, ri) => (r || []).map(c => ({
                text: String(c ?? ''),
                options: { color: FA_EXPORT_PALETTE.txt, fontSize: 11, fill: { color: ri % 2 === 0 ? FA_EXPORT_PALETTE.white : FA_EXPORT_PALETTE.tileGray } },
            })));
            // tw_stock_db客製: 2026-09-22使用者要求——原本autoPage:false明確
            // 關掉pptxgenjs自帶的表格跨頁機制，一張投影片塞不下的長表格會
            // 直接溢出投影片邊界（看不到的列，不是切到下一頁）。改成打開
            // autoPage（pptxgenjs自己會估算表格實際渲染高度是否超過這張
            // 投影片剩餘空間，超過就自動另外加一張投影片接續），
            // autoPageRepeatHeader讓每張延續的投影片都重複第一列(headerRow)
            // 當表頭，不用自己手動切表格/複製表頭。延續出來的投影片是
            // pptxgenjs內部直接addSlide()產生，不會套用addHeadingSlideBase
            // 的白底＋標題列樣式，這是目前這個函式庫版本的既有限制，但至少
            // 資料完整不會被裁掉。
            s.addTable([headerRow, ...bodyRows], { x: 0.6, y: 1.3, w: 12.1, autoPage: true, autoPageRepeatHeader: true, autoPageHeaderRows: 1, border: { type: 'solid', color: FA_EXPORT_PALETTE.border, pt: 0.5 } });
        } else {
            s.addText(_faMdLiteToPlainText(slide.body), { x: 0.6, y: 1.3, w: 12.1, h: 5.7, fontFace: 'Calibri', fontSize: 15, color: FA_EXPORT_PALETTE.txt, align: 'left', valign: 'top', lineSpacingMultiple: 1.3, fit: 'shrink' });
        }
    });

    await _faAppendVisualSnapshotSlides(pres, addHeadingSlideBase, visualSnapshots);

    return pres.write({ outputType: 'blob' });
}

// tw_stock_db客製: 2026-09-16——見_faMarkdownToPdfBlob裡使用處的說明，讀出
// 一個data URL圖片實際的自然寬高，讓PDF嵌入能自己算出等比例縮放後的
// width+height，不依賴pdfmake「只給width會自動等比例」這個沒有白紙黑字
// 保證的內建行為。
function _faGetImageNaturalSize(dataUrl) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve({ w: img.naturalWidth, h: img.naturalHeight });
        img.onerror = () => reject(new Error('無法讀取圖片尺寸'));
        img.src = dataUrl;
    });
}

async function _faMarkdownToPdfBlob(markdownText, heading, visualSnapshots) {
    await _faLoadScriptOnce(FA_ASSET_URLS.pdfmake);
    await _faLoadScriptOnce(FA_ASSET_URLS.pdfmakeFonts);
    await _faEnsureCjkFontRegistered();
    const pdfMake = window.pdfMake;

    const content = [
        { text: heading, style: 'h1' },
        { text: new Date().toLocaleDateString('zh-TW'), style: 'subtitle', margin: [0, 2, 0, 16] },
    ];
    _faMarkdownToSlides(markdownText, heading).forEach((slide) => {
        content.push({ text: slide.heading || '', style: 'h2' });
        if (slide.type === 'table') {
            const cols = slide.columns || [];
            const rows = slide.rows || [];
            content.push({
                table: {
                    headerRows: 1,
                    widths: cols.map(() => '*'),
                    body: [
                        cols.map(c => ({ text: String(c ?? ''), style: 'tableHeader' })),
                        ...rows.map(r => (r || []).map(c => ({ text: String(c ?? ''), style: 'tableCell' }))),
                    ],
                },
                layout: {
                    fillColor: (rowIdx) => (rowIdx === 0 ? FA_EXPORT_PALETTE.navy : (rowIdx % 2 === 0 ? FA_EXPORT_PALETTE.tileGray : null)),
                    hLineColor: () => FA_EXPORT_PALETTE.border, vLineColor: () => FA_EXPORT_PALETTE.border,
                    hLineWidth: () => 0.5, vLineWidth: () => 0.5,
                },
            });
        } else {
            content.push({ text: _faMdLiteToPlainText(slide.body), style: 'body' });
        }
        content.push({ text: '', margin: [0, 4, 0, 4] });
    });

    // tw_stock_db客製: 3D場景/繪圖截圖同樣以圖片content item加進去（見
    // _faAppendVisualSnapshotSlides在PPTX那邊的說明，這裡是PDF版本）。
    // 互動viewer是文字摘要（kind==='viewer_summary'），不是截圖。
    const VISUAL_KIND_LABEL = { image: '🖼️ 圖表', scene3d: '🧊 3D場景', drawing: '🎨 繪圖', mermaid: '📊 UML/流程圖', viewer_summary: '📝 互動表單內容', terminal: '🖥️ 終端機記錄' };
    // tw_stock_db客製: 2026-09-16使用者明確立下的硬規則——「所有圖片嵌入
    // pptx, pdf的時候，必須完全遵守一個規則：圖片必須等比例縮放」。這裡
    // 原本只給image一個width（460），依賴pdfmake「只給width時會依圖片本身
    // 比例自動算height」這個沒有白紙黑字保證的內建行為——改成自己用
    // _faGetImageNaturalSize()讀出圖片實際的寬高，明確算出等比例縮放後的
    // width+height兩個數字都給，不再依賴第三方函式庫的隱性行為。任何之後
    // 新增的圖片嵌入（不管PPTX還是PDF）都要遵守同一條規則：PPTX用
    // sizing:{type:'contain'}（見_faAppendVisualSnapshotSlides），PDF用
    // 這裡這種「自己算出width+height兩個值都給」的做法，不能只給單邊尺寸
    // 賭函式庫會自動處理。
    for (const snap of (visualSnapshots || [])) {
        if (!snap) continue;
        content.push({ text: VISUAL_KIND_LABEL[snap.kind] || '視覺內容', style: 'h2' });
        try {
            if ((snap.kind === 'viewer_summary' || snap.kind === 'terminal') && snap.text) {
                content.push({ text: _faMdLiteToPlainText(snap.text), style: 'body' });
            } else if (snap.dataUrl) {
                const maxW = 460, maxH = 620; // PDF單頁可用寬高的保守經驗值，避免圖片本身太高被裁切
                let imgOpts = { image: snap.dataUrl, width: maxW, alignment: 'center' };
                try {
                    const { w, h } = await _faGetImageNaturalSize(snap.dataUrl);
                    if (w > 0 && h > 0) {
                        const scale = Math.min(maxW / w, maxH / h, 1); // 不超過任一邊界，也不放大原本就小的圖
                        imgOpts = { image: snap.dataUrl, width: Math.round(w * scale), height: Math.round(h * scale), alignment: 'center' };
                    }
                } catch (_) { /* 讀不到自然尺寸時退回只給width，讓pdfmake自己嘗試等比例縮放 */ }
                content.push(imgOpts);
            }
        } catch (_) { /* 個別截圖/摘要嵌入失敗不影響其餘內容 */ }
        content.push({ text: '', margin: [0, 4, 0, 4] });
    }

    // 深度掃過整個content樹，把pdfmake載入的CJK字型不涵蓋的全形標點換成
    // 安全等效字（見_faSanitizePdfText說明），所有text節點統一在這裡
    // 處理一次，不用在上面組字串的地方各自記得呼叫。
    (function deepSanitize(node) {
        if (Array.isArray(node)) { node.forEach(deepSanitize); return; }
        if (!node || typeof node !== 'object') return;
        if (typeof node.text === 'string') node.text = _faSanitizePdfText(node.text);
        else if (Array.isArray(node.text)) deepSanitize(node.text);
        for (const v of Object.values(node)) {
            if (Array.isArray(v) || (v && typeof v === 'object')) deepSanitize(v);
        }
    })(content);

    const docDefinition = {
        pageSize: 'A4',
        pageMargins: [48, 56, 48, 56],
        footer: (currentPage, pageCount) => ({
            text: `第 ${currentPage} / ${pageCount} 頁`, alignment: 'center', fontSize: 8, color: FA_EXPORT_PALETTE.muted, margin: [0, 8, 0, 0],
        }),
        content,
        styles: {
            h1: { fontSize: 22, bold: true, color: FA_EXPORT_PALETTE.navy, margin: [0, 0, 0, 4] },
            h2: { fontSize: 14, bold: true, color: FA_EXPORT_PALETTE.navy, margin: [0, 10, 0, 6] },
            subtitle: { fontSize: 11, color: FA_EXPORT_PALETTE.muted, italics: true },
            body: { fontSize: 10.5, color: FA_EXPORT_PALETTE.txt, lineHeight: 1.35 },
            tableHeader: { fontSize: 10, bold: true, color: '#FFFFFF', fillColor: FA_EXPORT_PALETTE.navy, margin: [4, 4, 4, 4] },
            tableCell: { fontSize: 9.5, color: FA_EXPORT_PALETTE.txt, margin: [4, 4, 4, 4] },
        },
        defaultStyle: { font: 'NotoSansTC' },
    };

    return new Promise((resolve, reject) => {
        try { pdfMake.createPdf(docDefinition).getBlob(resolve); } catch (e) { reject(e); }
    });
}

// tw_stock_db客製: 2026-09-17使用者要求——Advance設定分頁太多、要分組
// 展開/收合（AI一組/多媒體一組/桌面程式單機一組）。cats是分到這一組的
// data-cat清單，順序即側欄顯示順序；「自訂函式」「檔案存取管理」使用者
// 確認一併歸類到AI組（都是給AI用的能力，跟host是web還是桌面版無關）。
// desktop組cats刻意留空陣列——目前沒有任何真正桌面專屬的設定項目，
// 這一組只是先把容器/收合UI建好，等以後真的有桌面專屬設定時再填入；
// 純網頁版不需要看到這個空group，所以預設visible:false，只有bootstrap.js
// 呼叫setAdvancedSettingsGroupVisible('desktop', true)才會顯示（見該方法
// 說明），呼應本次work session確立的「host專屬行為一律靠override注入、
// 不要讓共用引擎自己猜host是誰」原則——這裡引擎完全不檢查
// window.desktopAPI之類的全域變數，純粹由host自己決定要不要打開。
