        registerOptional('coding_run_tests',
            '在瀏覽器內的bash/python沙盒執行測試：把專案的文字檔（排除.git/node_modules等，單檔≤300KB、總量≤4MB）複製進沙盒/work後，執行你給的bash腳本（工作目錄已在/work）。支援python/python3（直接執行測試腳本檔，`python -m ...`不支援）、jq、grep/sed/awk等。**沒有node、沒有網路**——JS/TS專案的測試在這裡跑不了，要誠實告知使用者。沙盒內的修改不會寫回專案。參數: {"cwd_abs":"fap:我的專案","script":"python test_calc.py"}',
            codingWrap(async function (parsed) {
                const { io } = await codingRoot.call(this, parsed);
                const script = String(parsed.script || '').trim();
                if (!script) return { ok: false, error: '缺少script（要在沙盒/work執行的bash腳本，例如 python test_calc.py）' };
                const r = await this._codingRunInSandbox(io, script);
                return { ok: true, ...r, note: 'ok只代表腳本有執行；測試是否通過請讀stdout/stderr文字與exit_code（0通常代表成功，但不保證）。' };
            }),
            { type: 'object', properties: { cwd_abs: codingRootSchema, script: { type: 'string', description: '要執行的bash腳本，例如 python test_calc.py 或 sh run_tests.sh' } }, required: ['cwd_abs', 'script'], additionalProperties: false }
        );

        registerOptional('coding_run_check',
            '對指定檔案做語法檢查（不執行程式）：.py（Python ast）、.js/.mjs/.cjs（acorn）、.json、.sh（sh -n）。其他副檔名會回報「不支援檢查」。參數: {"cwd_abs":"fap:我的專案","paths":["src/calc.py","config.json"]}',
            codingWrap(async function (parsed) {
                const { io } = await codingRoot.call(this, parsed);
                const paths = Array.isArray(parsed.paths) ? parsed.paths.map(String) : (parsed.path ? [String(parsed.path)] : []);
                if (!paths.length) return { ok: false, error: '缺少paths（要檢查的檔案路徑陣列）' };
                return this._codingSyntaxCheck(io, paths);
            }),
            { type: 'object', properties: { cwd_abs: codingRootSchema, paths: { type: 'array', items: { type: 'string' } } }, required: ['cwd_abs', 'paths'], additionalProperties: false }
        );
        registerOptional('coding_workspace',
            '程式設計任務的暫存工作區（網頁版）。action: open（source=使用者專案資料夾的File Access Point參照 fap:名稱/子路徑，可選subpath只複製子資料夾；把專案複製一份到瀏覽器內部儲存OPFS並git init，回傳workspace_path=fap:ws-...與要告訴使用者的tell_user；已存在就接續）、status（cwd_abs=workspace_path，列出還沒轉移的新增/修改/刪除）、deploy（cwd_abs=workspace_path；dry_run:true只預覽；轉移回使用者資料夾，逐檔備份、寫入、讀回比對；使用者原檔在這段期間被改過會列為conflicts不覆蓋，force:true才強制）、discard（cwd_abs=workspace_path，刪除暫存區）。',
            codingWrap(async function (parsed) {
                const ws = String(parsed.cwd_abs || parsed.workspace_path || '').trim();
                if (parsed.action === 'open') return this._codingWsOpen({ source: parsed.source || parsed.source_path, subpath: parsed.subpath });
                if (parsed.action === 'status') return this._codingWsStatus(ws);
                if (parsed.action === 'deploy') return this._codingWsDeploy(ws, { dryRun: !!parsed.dry_run, force: !!parsed.force });
                if (parsed.action === 'discard') return this._codingWsDiscard(ws);
                return { ok: false, error: 'action必須是open/status/deploy/discard' };
            }),
            { type: 'object', properties: {
                action: { type: 'string', enum: ['open', 'status', 'deploy', 'discard'] },
                source: { type: 'string', description: 'open：使用者專案資料夾，格式fap:<名稱或id>[/<子路徑>]' },
                subpath: { type: 'string', description: 'open：選填，只複製這個子資料夾（專案太大時用）' },
                cwd_abs: { type: 'string', description: 'status/deploy/discard：workspace_path（fap:ws-...）' },
                dry_run: { type: 'boolean' }, force: { type: 'boolean' },
            }, required: ['action'], additionalProperties: false }
        );
        // ==== CODING-TOOLS-END ====

        // ==== SKILLS-BC-TOOLS-BEGIN ====
        // tw_stock_db客製: 2026-09-20 `skills` domain工具（產生Claude格式skill）。
        const skillWrap = (fn) => async function (rawArgs) {
            let parsed = {};
            try { parsed = await this.repairJsonPayload(String(rawArgs || '{}')); } catch (_) {}
            try { return JSON.stringify(await fn.call(this, parsed)); }
            catch (err) { return JSON.stringify({ ok: false, error: String(err.message || err) }); }
        };
        registerOptional('skill_create',
            '建立（或用overwrite:true更新）一個Claude格式的skill：SKILL.md（自動組出name/description frontmatter）＋選填的scripts/references/assets檔案。建立後立刻出現在Advance Settings的Skill分頁、可當domain使用。dry_run:true只驗證並回傳產生的SKILL.md不儲存。download:true會下載.skill壓縮檔（可放進Claude的skills資料夾）；save_to填File Access Point資料夾（fap:名稱/子路徑）會把整個skill資料夾寫進去。**files參數是合併、不是整包覆蓋**：overwrite:true更新既有skill時，這次files裡提到的路徑會被這次的新內容取代，先前已經存過、這次沒提到的路徑會維持原樣不會被清掉——依賴檔案很多、內容加起來很長時，直接分成好幾次呼叫、每次只帶幾個檔案即可，不用、也不要為了「一次到位」把所有檔案硬塞進同一次呼叫（單次呼叫的參數太長時，容易讓子任務生不出完整的工具呼叫而卡住重試）。參數: {"name":"pdf-form-filler","description":"做什麼＋什麼時候該用","body":"SKILL.md的Markdown內容(不含frontmatter)","files":[{"path":"references/api.md","content":"..."},{"path":"scripts/fill.py","content":"..."}],"overwrite":false,"dry_run":false,"download":false,"save_to":"fap:我的技能"}',
            skillWrap(function (p) { return this._skillCreate(p); }),
            { type: 'object', properties: {
                name: { type: 'string', description: '小寫英文/數字/連字號，最長64字元，不可含anthropic/claude' },
                description: { type: 'string', description: '最長1024字元：這個skill做什麼、什麼情境/關鍵字該觸發它（第三人稱）' },
                body: { type: 'string', description: 'SKILL.md主體(Markdown)，不要自己寫frontmatter，建議500行內' },
                files: { type: 'array', items: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] } },
                overwrite: { type: 'boolean' }, dry_run: { type: 'boolean' }, download: { type: 'boolean' },
                save_to: { type: 'string', description: 'File Access Point資料夾，格式fap:<名稱或id>[/<子路徑>]' },
            }, required: ['name', 'description', 'body'], additionalProperties: false }
        );
        registerOptional('skill_list',
            '列出目前app內所有skill（名稱、description、附帶檔案清單、是否啟用）。',
            skillWrap(async function () { return { ok: true, skills: this._skillList() }; }),
            { type: 'object', properties: {}, additionalProperties: false }
        );
        registerOptional('skill_read',
            '讀取一個既有skill的SKILL.md與檔案清單；帶path則讀取該skill內某個附帶檔案的內容。修改既有skill前一定要先讀取，不要憑記憶重寫。參數: {"name":"skill名稱","path":"references/api.md"}',
            skillWrap(function (p) { return this._skillRead(p.name, p.path); }),
            { type: 'object', properties: { name: { type: 'string' }, path: { type: 'string' } }, required: ['name'], additionalProperties: false }
        );

        // tw_stock_db客製: 2026-09-20 `browser_control` domain工具（Chrome擴充功能）。
        const bcTool = (name, cmd, desc, props, required, timeoutMs) => registerOptional(name, desc,
            async function (rawArgs) {
                let parsed = {};
                try { parsed = await this.repairJsonPayload(String(rawArgs || '{}')); } catch (_) {}
                try { return JSON.stringify(this._bcShapeResult(cmd, await this._bcCall(cmd, parsed, timeoutMs || 30000))); }
                catch (err) { return JSON.stringify({ ok: false, error: String(err.message || err) }); }
            },
            { type: 'object', properties: props, required: required || [], additionalProperties: false }
        );
        const tabIdProp = { type: 'integer', description: '分頁id（browser_create_tab/browser_list_tabs取得）。可省略或給過期的id：找不到分頁時會自動在「AI Controlled」群組開新分頁並在回傳的tab_recovered.new_tab_id告訴你新id' };
        bcTool('browser_status', 'ping', '檢查Chrome擴充功能是否已安裝、已連線、這個網站/桌面版是否已被允許。開始任何瀏覽器操作前先呼叫一次。', {}, [], 10000);
        bcTool('browser_create_tab_group', 'tab_group_create', '在固定的「AI Controlled」分頁群組（表示這些分頁由AI控制；不存在會自動建立、已存在就直接加入，永遠只有這一個群組）開啟一到多個網址。回傳group_id與每個分頁的tab_id。**開出來的分頁不會被切到前景（不打擾使用者），任務做完你自己要用browser_close關掉；回合結束時沒關的也會被自動關閉。** 只有使用者明確要「看到這個頁面」時，才用active（切到前景）或keep_open（回合結束後保留）。參數: {"urls":["https://example.com"]}。',
            { urls: { type: 'array', items: { type: 'string' } }, url: { type: 'string' }, active: { type: 'boolean', description: '是否把第一個分頁切到前景（會打擾使用者，只有使用者要看時才用），預設false；用active開的分頁回合結束後會保留' }, keep_open: { type: 'boolean', description: '回合結束後不要自動關閉這些分頁（只有使用者要留著看時才用），預設false' } }, []);
        bcTool('browser_create_tab', 'tab_create', '開一個新分頁，一律放進「AI Controlled」分頁群組。回傳tab_id。**新分頁不會切到前景（不打擾使用者）；用完要自己用browser_close關掉，回合結束時沒關的也會被自動關閉。** 只有使用者明確要「看到這個頁面」時才用active（切到前景）或keep_open（回合結束後保留）。',
            { url: { type: 'string' }, active: { type: 'boolean', description: '切到前景（會打擾使用者，只有使用者要看時才用）；用active開的分頁回合結束後會保留' }, keep_open: { type: 'boolean', description: '回合結束後不要自動關閉這個分頁（只有使用者要留著看時才用）' } }, ['url']);
        bcTool('browser_list_tabs', 'tab_list', '列出助理建立、仍開著的分頁與分頁群組（只包含助理自己開的，看不到使用者原本的分頁）。', {}, []);
        bcTool('browser_navigate', 'tab_navigate', '讓分頁前往新網址，或 action 為 back/forward/reload。等頁面載入完成才回傳。',
            { tab_id: tabIdProp, url: { type: 'string' }, action: { type: 'string', enum: ['goto', 'back', 'forward', 'reload'] } }, []);
        bcTool('browser_close', 'tab_close', '關閉一個分頁（tab_id）或整個分頁群組（group_id）。只能關閉助理自己開的。**任務做完、不再需要的分頁就用這個關掉**（最後一個分頁關掉時空的「AI Controlled」群組會自動消失）。', { tab_id: tabIdProp, group_id: { type: 'integer' } }, []);
        bcTool('browser_activate_tab', 'tab_activate', '把分頁切到前景（讓使用者看到）。會打擾使用者正在做的事，只有使用者明確要看這個頁面時才用；被切到前景的分頁回合結束後會保留、不會被自動關閉。點擊/打字/截圖等操作不需要先切到前景。', { tab_id: tabIdProp }, []);
        bcTool('browser_scroll', 'scroll', '在分頁內捲動。direction: down/up/top/bottom/left/right；amount是像素（預設約一個畫面的80%）；selector可指定要捲動的容器。回傳目前scroll_y、是否已到底。',
            { tab_id: tabIdProp, direction: { type: 'string', enum: ['down', 'up', 'top', 'bottom', 'left', 'right'] }, amount: { type: 'number' }, selector: { type: 'string' } }, []);
        // tw_stock_db客製: 2026-09-26使用者要求——截圖要能「框選範圍(region
        // clip)」，而且AI要能真的看到截圖內容：region（分頁可視區內的像素
        // 座標，full_page:true時是整頁座標）、scale放大小範圍；save:true把
        // 截圖存成file_id（可餵給compare_images/interpret_image）；
        // interpret:true（＋question）直接用vision model看這張截圖並把描述
        // 帶進回傳的meta（meta會進模型看得到的content，圖片本身不會）。
        // region需要新版擴充功能（background.js的screenshot有region支援）：
        // 舊版會忽略region回整張畫面，擴充功能回傳region_applied才算生效，
        // 沒有的話在meta.warning講清楚，不要讓AI以為截到的是指定範圍。
        registerOptional('browser_screenshot',
            '對分頁截圖（畫面會顯示給使用者）。預設你只拿到尺寸與標題、看不到像素；**要讓自己看到截圖內容，帶interpret:true（可加question指定想看什麼）**，會用支援讀圖的model看這張圖並把描述放在回傳的description。region:{x,y,width,height}只截指定範圍（座標是分頁可視區像素、左上角0,0，跟browser_get_elements的座標同一套；full_page:true時改用整頁座標），scale(1~3)可放大小範圍讓文字更清楚。save:true把截圖存成圖片檔案（回傳file_id，之後可用compare_images跟其他圖片比對）。full_page:true截整頁（最高8000px）。要看頁面文字內容仍優先用browser_get_page_structure / browser_get_page_text。',
            async function (rawArgs) {
                let parsed = {};
                try { parsed = await this.repairJsonPayload(String(rawArgs || '{}')); } catch (_) {}
                try {
                    const region = parsed.region && typeof parsed.region === 'object' ? {
                        x: Number(parsed.region.x), y: Number(parsed.region.y),
                        width: Number(parsed.region.width), height: Number(parsed.region.height),
                    } : null;
                    if (region && !(Number.isFinite(region.x) && Number.isFinite(region.y) && region.width > 0 && region.height > 0)) {
                        return JSON.stringify({ ok: false, error: 'region需要{x,y,width,height}四個數字，width/height要大於0' });
                    }
                    const callArgs = Object.assign({}, parsed);
                    delete callArgs.interpret; delete callArgs.question; delete callArgs.save;
                    if (region) callArgs.region = region; else delete callArgs.region;
                    const result = this._bcShapeResult('screenshot', await this._bcCall('screenshot', callArgs, 45000));
                    if (!result || result.type !== 'image') return JSON.stringify(result);
                    if (region && !(result.meta && result.meta.region_applied)) {
                        // 擴充功能這一版沒有區域截圖：用整張圖在本機精準裁切（座標是畫面左上角0,0的像素，跟擴充功能回傳的width／height同一套）
                        try {
                            const cropped = await this._cropDataUrl(result.dataUrl, region, result.meta && result.meta.width);
                            result.dataUrl = cropped.dataUrl;
                            result.meta.region_applied = { x: cropped.x, y: cropped.y, width: cropped.width, height: cropped.height, by: 'local' };
                            result.meta.width = cropped.width; result.meta.height = cropped.height;
                            result.meta.note = '擴充功能沒有區域截圖功能，已在本機從整張截圖裁出指定範圍（x=' + cropped.x + ',y=' + cropped.y + ',' + cropped.width + '×' + cropped.height + '）。';
                        } catch (cropErr) {
                            result.meta.warning = '要求的範圍沒有裁成功（' + String((cropErr && cropErr.message) || cropErr) + '），這張是整個畫面／整頁。';
                        }
                    }
                    if (parsed.save || parsed.interpret) {
                        const blob = await (await fetch(result.dataUrl)).blob();
                        const shotName = `screenshot_${new Date().toISOString().replace(/[:.]/g, '-')}.jpg`;
                        result.meta.file_id = await this.fileCache.put(shotName, blob.type || 'image/jpeg', blob, 'uploaded');
                        result.meta.filename = shotName;
                    }
                    if (parsed.interpret) {
                        try {
                            const r = await this._interpretImageWithVisionModel(result.dataUrl, parsed.question);
                            result.meta.description = r.description;
                            result.meta.model_used = r.modelUsed;
                        } catch (err) {
                            result.meta.interpret_error = String(err.message || err);
                        }
                    }
                    return JSON.stringify(result);
                } catch (err) {
                    return JSON.stringify({ ok: false, error: String(err.message || err) });
                }
            },
            { type: 'object', properties: {
                tab_id: tabIdProp,
                full_page: { type: 'boolean' },
                quality: { type: 'integer' },
                region: { type: 'object', description: '只截這個範圍：{x,y,width,height}（像素，左上角0,0）', properties: { x: { type: 'number' }, y: { type: 'number' }, width: { type: 'number' }, height: { type: 'number' } } },
                scale: { type: 'number', description: '（選填）放大倍率1~3，搭配region放大小範圍' },
                save: { type: 'boolean', description: '（選填）把截圖存成圖片檔案，回傳file_id' },
                interpret: { type: 'boolean', description: '（選填）true＝用vision model實際看這張截圖，描述放在回傳的description' },
                question: { type: 'string', description: '（選填）搭配interpret，想問這張截圖的具體問題' },
            }, additionalProperties: false }
        );
        // tw_stock_db客製: 2026-09-22使用者要求——原本這兩個工具是「一次讀完
        // +max_chars硬截斷」，長文章讀不完也接不下去。改成跟fap_read_file/
        // parse_uploaded_file同一套分頁契約（offset/start_line/max_chars/
        // max_lines，回傳has_more/next_offset），實際分頁邏輯在擴充功能端
        // 的pageText()（web/browser-control-extension/background.js）。
        const pageParamsProps = {
            offset: { type: 'integer', description: '選填：從第幾個字元開始讀（分頁用，預設0）' },
            max_chars: { type: 'integer', description: '選填：這次最多讀幾個字元（預設12000）' },
            start_line: { type: 'integer', description: '選填：從第幾行開始讀（1起算，優先於offset）' },
            max_lines: { type: 'integer', description: '選填：這次最多讀幾行' },
        };
        bcTool('browser_get_page_text', 'get_page_text', '取得分頁的可見文字內容（innerText），含目前捲動位置。**分頁讀取**：回傳has_more:true代表還沒讀完，用offset（或start_line）繼續讀，長文章要分頁讀完整份，不要只看第一段就下結論。',
            Object.assign({ tab_id: tabIdProp }, pageParamsProps), []);
        // tw_stock_db客製: 2026-09-22使用者要求「圖文穿插」——原本圖片只會
        // 收斂成markdown裡的"[圖: alt]"文字，圖片實際內容完全看不到。這裡
        // 不用通用的bcTool（純轉發），改成自訂callback：先照常呼叫
        // get_page_structure拿到images清單（擴充功能端新增的欄位，見
        // background.js），interpret_images:true時再逐張呼叫
        // interpret_image用的同一套_interpretImageWithVisionModel補上
        // description欄位——沒有可用的vision model、或某張圖片解讀失敗，
        // 該張圖片就只留description_error，不影響其他圖片/整體結果。
        registerOptional('browser_get_page_structure',
            '以結構化方式讀取分頁內容（讀網頁的首選）：回傳標題階層(headings)、Markdown格式的正文(markdown，含標題/清單/表格/連結)、表格資料(tables，含欄位名稱與列)、連結清單(links)、圖片清單(images，含src/alt)、表單欄位(forms)。自動避開導覽列/頁尾等雜訊。**分頁讀取**：markdown欄位回傳has_more:true代表還沒讀完，用offset（或start_line）繼續讀，長文章要分頁讀完整份。**圖文穿插**：interpret_images:true時，會對前幾張圖片（interpret_images_count，預設5、最多10）自動呼叫vision model，把解讀結果填進images[].description（沒有配置支援讀圖的model、或該張圖片解讀失敗會是images[].description_error，不影響其他張）；這會增加額外的網路請求/延遲，圖片不是頁面重點時不要開。',
            async function (rawArgs) {
                let parsed = {};
                try { parsed = await this.repairJsonPayload(String(rawArgs || '{}')); } catch (_) {}
                let result;
                try { result = this._bcShapeResult('get_page_structure', await this._bcCall('get_page_structure', parsed, 30000)); }
                catch (err) { return JSON.stringify({ ok: false, error: String(err.message || err) }); }
                if (parsed.interpret_images && result && Array.isArray(result.images) && result.images.length) {
                    const n = Math.max(1, Math.min(10, Number(parsed.interpret_images_count) || 5));
                    for (const img of result.images.slice(0, n)) {
                        try {
                            const { dataUrl } = await this._resolveImageInputForInterpretation({ imageUrl: img.src });
                            const vres = await this._interpretImageWithVisionModel(dataUrl, img.alt ? `這張圖片的alt文字是「${img.alt}」，請描述圖片實際內容（如果圖片裡有文字，也請列出來）。` : undefined);
                            img.description = vres.description;
                        } catch (err) {
                            img.description_error = String(err.message || err);
                        }
                    }
                }
                return JSON.stringify(result);
            },
            { type: 'object', properties: Object.assign({ tab_id: tabIdProp }, pageParamsProps, {
                interpret_images: { type: 'boolean', description: '選填：true時對前幾張圖片自動呼叫vision model補上description（見上方工具說明）' },
                interpret_images_count: { type: 'integer', description: '選填：搭配interpret_images，要解讀前幾張圖片，預設5、最多10' },
            }), required: [], additionalProperties: false }
        );
