                if (stEl) stEl.innerHTML = st.serverError ? `⚠️ ${this._escapeHtml(st.serverError)}` : (st.connected ? `🟢 擴充功能已連線${st.extensionVersion ? '（版本 ' + this._escapeHtml(st.extensionVersion) + '）' : ''}，本機連接埠 ${st.port}` : `⚪ 擴充功能尚未連線（本機連接埠 ${st.port}）`);
